import{z as s,x as o,o as e,c as A,q as t,j as i,D as E,d as n,s as B,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"美式期权与提前行权","description":"","frontmatter":{"title":"美式期权与提前行权","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/american-exercise.md","filePath":"quant/american-exercise.md","lastUpdated":1791063341000}'),p={name:"quant/american-exercise.md"};function C(m,a,d,h,c,S){const r=o("Mermaid");return e(),A("div",null,[a[2]||(a[2]=t('<h1 id="美式期权与提前行权" tabindex="-1">美式期权与提前行权 <a class="header-anchor" href="#美式期权与提前行权" aria-label="Permalink to &quot;美式期权与提前行权&quot;">​</a></h1><div class="epigraph"><p>美式期权的价值是在停时上取支付贴现的本质确界；最小二乘回归用路径上的基函数估计续持价值，使模拟也能处理提前行权。</p><footer>—— Longstaff and Schwartz, Valuing American Options by Simulation: A Simple Least-Squares Approach, Review of Financial Studies, 2001</footer></div><p><a href="/quant/risk-neutral-pricing">上一课</a>把无套利写成等价鞅测度：可复制支付是货币账户计价下的 \\(\\mathbb{Q}\\)-条件期望，树、PDE、MC 是同一期望的三种计算。缺口是美式把行权权交给持有人，价格变成最优停时，没有欧式那样的简单闭式。无股利美式看涨与欧式同价；有股利的看涨与通常的看跌存在自由边界。本课写执行条件与 LSMC，不重推 Girsanov 与 \\(N(d_1)\\)。数值网格接到已写的 <a href="/quant/binomial-tree">二叉树</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>持有美式看跌时，立刻行权得到 \\(K-S\\)，现金可吃利息；继续持有则保留保险——股票再跌还能赚、反弹则损失有限。利率越高、剩余期限越短、越是深度实值，利息动机越强，保险越不值钱，越可能执行。看涨对称：无股利时持有标的没有分红损失，提前执行丢掉保险又丢掉延迟支付执行价的利息，故永不执行，美式与欧式同价。有离散或连续股利时，除权前可能执行以锁定股利。问题是刻画执行区域，并计算</p> \\[V_0=\\sup_{\\tau\\in\\mathcal{T}} \\mathbb{E}^{\\mathbb{Q}}\\bigl[e^{-r\\tau}g(S_\\tau)\\bigr], \\]<p>其中 \\(g\\) 为内在价值，\\(\\mathcal{T}\\) 为允许停时集合。这不是一个普通期望，而是对策略取本质确界。</p><p>美式看跌的行权决策是两股力量的拉扯——回答「什么时候立刻行权比继续持有划算」：</p>',8)),(e(),i(l,null,{default:E(()=>[B(r,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOLD%5B%22%E6%8C%81%E6%9C%89%E6%B7%B1%E5%BA%A6%E5%AE%9E%E5%80%BC%E7%BE%8E%E5%BC%8F%E7%9C%8B%E8%B7%8C%22%5D%20--%3E%20A%5B%22%E7%AB%8B%E5%88%BB%E8%A1%8C%E6%9D%83%EF%BC%9A%E6%8B%BF%20K-S%EF%BC%8C%E7%8E%B0%E9%87%91%E5%90%83%E5%88%A9%E6%81%AF%22%5D%0A%20%20HOLD%20--%3E%20B%5B%22%E7%BB%A7%E7%BB%AD%E6%8C%81%E6%9C%89%EF%BC%9A%E4%BF%9D%E7%95%99%E4%BF%9D%E9%99%A9%E4%B8%8E%E6%97%B6%E9%97%B4%E4%BB%B7%E5%80%BC%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E5%88%A9%E6%81%AF%E5%8A%A8%E6%9C%BA%EF%BC%9A%E5%88%A9%E7%8E%87%E9%AB%98%E3%80%81%E6%9C%9F%E9%99%90%E7%9F%AD%E3%80%81%E8%B6%8A%E5%AE%9E%E5%80%BC%E8%B6%8A%E5%BC%BA%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E4%BF%9D%E9%99%A9%E4%BB%B7%E5%80%BC%EF%BC%9A%E8%BF%98%E5%8F%AF%E8%83%BD%E5%86%8D%E8%B7%8C%EF%BC%8C%E5%8F%8D%E5%BC%B9%E6%8D%9F%E5%A4%B1%E6%9C%89%E9%99%90%22%5D%0A%20%20A1%20--%3E%20D%7B%22%E5%88%A9%E6%81%AF%E6%94%B6%E7%9B%8A%E5%A4%A7%E4%BA%8E%E4%BF%9D%E9%99%A9%E4%BB%B7%E5%80%BC%EF%BC%9F%22%7D%0A%20%20B1%20--%3E%20D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20EX%5B%22%E8%BF%9B%E5%85%A5%E6%89%A7%E8%A1%8C%E5%8C%BA%E5%9F%9F%22%5D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20CO%5B%22%E7%95%99%E5%9C%A8%E7%BB%AD%E6%8C%81%E5%8C%BA%E5%9F%9F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>离散行权日的百慕大是中间物：倒推只在行权日做 \\(\\max\\)，其余日期按欧式贴现。许多可转债与雇员期权其实是百慕大。连续美式是百慕大在行权日加密后的极限。</p><p><span class="marginnote">「百慕大」这个名字取自介于「美式（American）」与「欧式（European）」之间的地理位置：行权机会介于「任何时候」与「只到期日一次」之间，只在约定的若干日期可提前行权。可转债的转股窗口、雇员期权的归属日，实际都是百慕大结构。</span></p><h3 id="无股利看涨永不提前" tabindex="-1">无股利看涨永不提前 <a class="header-anchor" href="#无股利看涨永不提前" aria-label="Permalink to &quot;无股利看涨永不提前&quot;">​</a></h3><p>Merton 的论证不依赖对数正态：若利率非负、无股利，美式看涨的欧式部分已经满足 \\(C_{\\mathrm{E}}\\ge S-K e^{-rT}\\gt S-K\\)（\\(r\\gt 0,T\\gt 0\\)），提前执行拿到 \\(S-K\\) 严格吃亏。\\(r=0\\) 时不等式变成弱的，执行无益也无害。有股利时 \\(C_{\\mathrm{E}}\\) 可以掉到内在价值以下，欧式允许这种「便宜」，美式不允许，必须用执行把价格托到 \\(g\\) 之上。看跌即使无股利也可能执行：深度实值看跌像短期限债券，持有它损失 \\(K\\) 的利息。</p><p><span class="marginnote">「美式一定比欧式贵」只在同一支付、同一可交易对冲下因为策略集更大才成立。若欧式有更好的现金用途或美式有离散观察限制，数字上仍可能接近。无股利看涨则严格相等，不是「几乎相等」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>低维用倒推。树或差分网格在每个点比较 \\(g(S)\\) 与贴现的后继期望（续持）。执行区域的边界 \\(S^*(t)\\) 是使二者相等的点，通常光滑性有限，看跌的 \\(S^*(t)\\) 随 \\(t\\to T\\) 升向 \\(K\\)。Barone-Adesi-Whaley（1987）对美式给出二次近似闭式，速度快但有偏；Kim（1990）等把价格写成欧式加上提前行权溢价的积分方程。这些对单资产香草有用，对多资产或路径依赖不够。</p><p>Longstaff-Schwartz 的 LSMC 在 \\(\\mathbb{Q}\\) 下模拟路径（通常是风险中性几何布朗或已校准的因子模型），从到期向前：到期只能执行，\\(V_T=g(S_T)\\)。在行权日 \\(t_k\\)，对仍实值的路径，用基函数 \\(\\psi_j(S_{t_k})\\)（多项式、Laguerre 等）回归后续路径的贴现现金流，得到续持估计 \\(\\hat{C}(S)=\\theta\\cdot\\psi(S)\\)。若 \\(g(S)\\gt \\hat{C}(S)\\) 则执行，该路径此后的现金流被改写成当下的 \\(g(S)\\)。全部日期走完后，把每条路径第一次执行的贴现现金流平均，得到价格。回归只用实值路径，是为了把函数逼近集中在可能执行的区域。</p><p><span class="marginnote">代入一个数：立刻行权拿到 \\(K-S=20\\) 元现金，年利率 5%，一年的利息就是 1 元；若剩余期限一年，继续持有的「保险」至少要值 1 元才划算。快到期时保险趋近于零，利息动机赢——这正是看跌的执行边界随 \\(t\\to T\\) 升向 \\(K\\) 的直觉。</span></p><h3 id="回归与下偏倚、上偏倚" tabindex="-1">回归与下偏倚、上偏倚 <a class="header-anchor" href="#回归与下偏倚、上偏倚" aria-label="Permalink to &quot;回归与下偏倚、上偏倚&quot;">​</a></h3><p>LSMC 用同一组路径既估续持又决策，有向下的偏差：回归是样本内的近似策略，不是真正的最优停时，得到的是某个（次优）停时的价格，因而是真值的下界（忽略模拟方差时）。要上界需要对偶方法，如 Andersen-Broadie 用嵌套模拟估鞅对偶；实践中常加大基函数与路径数，看价格稳定。Glasserman 强调：美式模拟的误差结构与欧式不同，除方差外还有策略偏差。基函数选错会系统性早执行或晚执行；状态变量必须包含马尔可夫因子，亚式要把平均价格放进回归，否则信息不足。</p><p><span class="marginnote">「下偏倚」可以这样记：LSMC 在同一批样本上既学习规则又用规则考试，成绩天然偏向自己——但它学到的只是次优策略，次优策略的价格只会不高于最优价格，所以偏差朝下。对偶方法从上往下压出上界，两界夹住真值，中间的缝隙就是策略近似的代价。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>提前行权把 PDE 变成不等式：在续持区域是 Black-Scholes 方程，在执行区域 \\(V=g\\)，二者在自由边界相接，通常要求价值匹配与平滑粘贴（\\(\\Delta\\) 连续）。互补形式是</p> \\[\\max\\bigl(g-V,\\; V_t+(r-q)SV_S+\\tfrac12\\sigma^2 S^2 V_{SS}-rV\\bigr)=0, \\]<p>这是有限差分里投影与惩罚法的来源。经济上，平滑粘贴意味着在最优边界上再微调执行不会一阶改变价值；若 \\(\\Delta\\) 跳跃，持有人可以靠把边界略移来套利式地改进。</p><p>风险中性叙事仍然成立：只是期望换成停时上的 \\(\\sup\\)。对冲在执行边界附近 \\(\\Gamma\\) 很大，离散对冲困难；做市商必须预期到对方的最优执行，而不是假设合约活到 \\(T\\)。雇员期权还常有离职强迫执行与不可交易约束，Longstaff-Schwartz 原文讨论的是可交易美式，雇员合约要另加流失率，不能直接当同一价格。</p><p><span class="marginnote">LSMC 估的是价格，顺带给出一个执行规则。那个规则是回归出来的近似，不是解析 \\(S^*(t)\\)。报告「模型里的执行边界」时，应说明是哪组基函数、哪组路径上的分类结果，避免画成定理中的自由边界。</span></p>',18)),(e(),i(l,null,{default:E(()=>[B(r,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%88%B0%E6%9C%9F%3A%20%E5%8F%AA%E8%83%BD%E6%89%A7%E8%A1%8C%20g(S_T)%22%5D%20--%3E%20R%5B%22%E4%B8%8A%E4%B8%80%E8%A1%8C%E6%9D%83%E6%97%A5%3A%20%E5%AE%9E%E5%80%BC%E8%B7%AF%E5%BE%84%E5%9B%9E%E5%BD%92%E7%BB%AD%E6%8C%81%22%5D%0A%20%20R%20--%3E%20Cmp%5B%22%E6%AF%94%E8%BE%83%20g%20%E4%B8%8E%20%C4%88%22%5D%0A%20%20Cmp%20--%3E%7C%22g%20%3E%20%C4%88%22%7C%20Ex%5B%22%E6%89%A7%E8%A1%8C%2C%20%E9%94%81%E5%AE%9A%20g%22%5D%0A%20%20Cmp%20--%3E%7C%22g%20%E2%89%A4%20%C4%88%22%7C%20H%5B%22%E7%BB%AD%E6%8C%81%2C%20%E6%B2%BF%E7%94%A8%E5%90%8E%E7%BB%AD%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%0A%20%20Ex%20--%3E%20Avg%5B%22%E8%B4%B4%E7%8E%B0%E7%8E%B0%E9%87%91%E6%B5%81%E5%B9%B3%E5%9D%87%22%5D%0A%20%20H%20--%3E%20Avg%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h3 id="百慕大、离散股利与雇员期权" tabindex="-1">百慕大、离散股利与雇员期权 <a class="header-anchor" href="#百慕大、离散股利与雇员期权" aria-label="Permalink to &quot;百慕大、离散股利与雇员期权&quot;">​</a></h3><p>许多可转债与雇员期权只能在离散日期行权，是百慕大：倒推只在那些日期做 \\(\\max\\)，其余时间按欧式贴现。加密行权日则趋向连续美式。离散股利把执行动机集中在除权前夕，自由边界在除权日附近跳跃，网格必须对齐除权日历。雇员期权常附带归属期、离职强迫执行与禁止转让，流失率会降低提前执行的期权价值，不能直接套用可交易美式的 \\(S^*(t)\\)。LSMC 仍可用，但回归要加入可执行标志与流失随机性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>连续路径、单因子、可观测马尔可夫状态，是倒推网格的舒适区。跳跃使自由边界问题更绕；随机波动要把 \\(v\\) 放进状态，二维 PDE 或二维树可行，LSMC 则把 \\(v\\) 放进回归。可赎回、可转换叠了发行人本息与持有人转股，是双方停时，比单边美式难，通常仍用倒推或 LSMC 的扩展。离散股利在除权瞬间造成 \\(S\\) 跳跃，执行决策集中在除权前夕，网格必须把除权日对齐。</p><p>LSMC 对虚值路径的执行信息少，深虚值美式看跌主要吃欧式尾部，回归要防止在几乎不执行的区域拟合噪声。路径过少、多项式次数过高会过拟合，表现为样本内价格虚高、样本外策略变差。与树比较：一维香草用 CRR 或差分更干净，LSMC 的理由是维数。不要用高维模拟去给一维美式看跌「再验证四位小数」，那不是它的设计点。</p><p><span class="marginnote">McKean（1965）与后续最优停时文献比 Longstaff-Schwartz 早得多。LSMC 不是美式定价的理论起点，而是高维可计算的策略近似。引用 2001 年论文时，应把它放在模拟算法而不是存在性定理上。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>美式价格是风险中性下停时的本质确界；无股利美式看涨等于欧式（Merton, 1973）。</li><li>看跌与有股利看涨存在执行区域，价格 = 欧式 + 提前行权溢价。</li><li>低维用树或 PDE 在每个节点取 \\(\\max(g,\\text{续持})\\)；自由边界满足平滑粘贴。</li><li>Longstaff-Schwartz（2001）用最小二乘估计续持，得到次优停时价格，通常是下界。</li><li>回归状态必须是马尔可夫充分统计量；基函数与实值路径筛选决定偏差。</li><li>一维香草优先网格；LSMC 服务于多资产、路径依赖与可转债一类。</li><li>出处：Merton, <em>Bell Journal</em>, 1973；Longstaff and Schwartz, <em>Review of Financial Studies</em>, 2001；二次近似见 Barone-Adesi and Whaley, <em>Journal of Finance</em>, 1987。</li></ul>',8))])}const u=s(p,[["render",C]]);export{D as __pageData,u as default};
